    reference["cases"][0]["report"]["records"] = json!([{
        "codepoint": 65, "glyph_id": 1, "output_bits": 3, "mono_threshold": 128,
        "gray_gamma": 1.0, "fitted_commands": [], "pixels": [0],
        "left": 0, "top": 0, "width": 1, "height": 1, "advance_26_6": 64,
