        rep["metrics"] = json!({"a": metrics});
        rep
    };
    let reference = doc(
        "ref",
        vec![
            sized_case(16, mk(json!([0, 0, 0]), 64, 1)),
            sized_case(24, mk(json!([0, 0, 0]), 64, 1)),
        ],
    );
    let mut b16 = record(65);
    b16["diagonal_pairs"] = json!([1, 2, 3]);
    let mut rep16 = report(vec![b16]);
