use super::*;

fn report(records: Vec<Value>) -> Value {
    json!({
        "source_sha256": "abc",
        "axes": {},
        "profile": "mono_1bit",
        "size_px": 16,
        "target": "t",
        "hinting_requested": false,
        "metrics": {"a": 1},
        "records": records,
    })
}

fn record(codepoint: i64) -> Value {
    json!({
        "codepoint": codepoint,
        "glyph_id": 1,
        "output_bits": 1,
        "mono_threshold": 128,
        "gray_gamma": 1.0,
        "fitted_commands": [],
        "pixels": [0],
        "left": 0,
        "top": 0,
        "width": 1,
        "height": 1,
        "advance_26_6": 64,
    })
}

fn case(report: Value) -> Value {
    json!({
        "family_id": "f",
        "size_px": 16,
        "axes": {},
        "profile": "mono_1bit",
        "report": report,
    })
}

fn sized_case(size: u64, report: Value) -> Value {
    json!({
        "family_id": "f",
        "size_px": size,
        "axes": {},
        "profile": "mono_1bit",
        "report": report,
    })
}

fn doc(variant: &str, cases: Vec<Value>) -> Value {
    json!({
        "characters": "ABC",
        "profiles": ["mono_1bit"],
        "variant": variant,
        "cases": cases,
    })
}

fn single() -> (Value, Value) {
    let reference = doc("ref", vec![case(report(vec![record(65)]))]);
    let proposal = doc("prop", vec![case(report(vec![record(65)]))]);
    (reference, proposal)
}

