        "repertoire/profile policies differ"
    );
    let (_, mut proposal) = single();
    proposal["profiles"] = json!(["gray_3bit"]);
    assert_eq!(
        compare(&reference, &proposal).unwrap_err(),
        "repertoire/profile policies differ"
