    let read = |path: &Path| -> Result<(Value, String), String> {
        let bytes = fs::read(path).map_err(|e| e.to_string())?;
        let value = serde_json::from_slice(&bytes).map_err(|e| e.to_string())?;
        Ok((value, format!("{:x}", Sha256::digest(bytes))))
