impl<'a> Bitmap<'a> {
    /// Returns `None` if `width * height` overflows or differs from `ink.len()`.
    pub fn new(width: usize, height: usize, ink: &'a [bool]) -> Option<Self> {
        if width.checked_mul(height) == Some(ink.len()) {
