mod tests {
    use super::*;

    #[test]
    fn roles_keep_approved_baseline_across_candidate_versions() {
        let approved = [
            ("ref", None, Some(RendererRole::Reference)),
            ("approved", Some("001.01"), Some(RendererRole::Baseline)),
        ];
        assert_eq!(select_roles(approved).unwrap(), ("approved", Some("ref")));
        for candidate in ["001.02", "002.01", "100.500"] {
            assert_eq!(
                select_roles(approved.into_iter().chain([(
                    "working",
                    Some(candidate),
                    Some(RendererRole::Candidate)
                )]))
                .unwrap(),
                ("working", Some("approved"))
            );
        }
        assert_eq!(
            select_roles([
                ("approved", Some("001.01"), Some(RendererRole::Baseline)),
                ("working", Some("001.02"), Some(RendererRole::Candidate)),
            ])
            .unwrap(),
            ("working", Some("approved"))
        );
        assert!(select_roles([
            ("ref", None, Some(RendererRole::Reference)),
            ("working", Some("001.02"), Some(RendererRole::Candidate)),
        ])
        .is_err());
    }

    #[test]
    fn latest_iteration_in_first_revision_compares_to_reference() {
        assert_eq!(
            select([
                ("new", Some("001.02")),
                ("ref", None),
                ("old", Some("001.01"))
            ])
            .unwrap(),
            ("new", Some("ref"))
        );
    }

    #[test]
    fn revision_and_iteration_are_ordered_numerically() {
        assert_eq!(
            select([
                ("ref", None),
                ("a", Some("9.10")),
                ("b", Some("9.2")),
                ("c", Some("10.2")),
                ("d", Some("10.10"))
            ])
            .unwrap(),
            ("d", Some("a"))
        );
    }

    #[test]
    fn invalid_or_ambiguous_versions_are_rejected() {
        for bad in ["iteration-1", "1.2.3", "0.1", "1.0", "1.-1", "4294967296.1"] {
            assert!(version(bad).is_err());
        }
        assert!(select([("ref", None), ("a", Some("001.01")), ("b", Some("1.1"))]).is_err());
        assert!(select([("a", None), ("b", None)]).is_err());
    }
}
use font_generator::specimens::publish;
use std::{env, path::Path, process::ExitCode};

fn run() -> Result<(), String> {
    let args: Vec<_> = env::args_os().skip(1).collect();
    if args.len() == 1 && (args[0] == "--help" || args[0] == "-h") {
        println!("Usage: font_specimens CONFIG.json OUTPUT_DIRECTORY");
        return Ok(());
    }
    if args.len() != 2 {
        return Err("usage: font_specimens CONFIG.json OUTPUT_DIRECTORY".into());
    }
    let result = publish(Path::new(&args[0]), Path::new(&args[1])).map_err(|e| e.to_string())?;
    println!(
        "Published {} packages, {} profile cases, {} images, {} failed/unsupported samples.",
        result.packages.len(),
        result.case_count,
        result.image_count,
        result.failure_count
    );
    println!(
        "Active specimens: {}",
        Path::new(&args[1]).join("active.json").display()
    );
    for package in result.packages {
        println!("Package: {package}");
    }
    Ok(())
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("font_specimens: {error}");
            ExitCode::FAILURE
        }
    }
}
