fn stable_renderer_roles_distinguish_approval_from_working_version_metadata() {
    let mut current: Value = serde_json::from_str(include_str!("../specimens.json")).unwrap();
    // Resolve role validation independently of the filesystem preview-policy
    // fixture; matrix protection is exercised separately with actual files.
    current.as_object_mut().unwrap().remove("preview_policy");
    assert!(resolve(current.clone()).is_ok());
    assert_eq!(current["variants"][0]["renderer"], "reference");
    assert_eq!(current["variants"][1]["renderer"], "baseline");
    for field in ["version", "extensions", "renderer"] {
        let mut invalid = current.clone();
        invalid["variants"][1][field] = json!(match field {
            "version" => "100.500",
            "extensions" => "none",
            _ => "reference",
        });
        assert!(resolve(invalid).is_err(), "baseline drift: {field}");
    }
    let mut working = current.clone();
    let mut candidate = current["variants"][1].clone();
    candidate["id"] = json!("working");
    candidate["renderer"] = json!("candidate");
    candidate["extensions"] = json!("font-hints-01");
    candidate["version"] = json!("100.500");
    working["variants"].as_array_mut().unwrap().push(candidate);
    working["defaults"]["variants"] = json!([current["variants"][1]["id"], "working"]);
    assert!(resolve(working).is_ok());
    current["variants"][1]["renderer"] = json!("candidate");
    assert!(resolve(current).unwrap_err().contains("legacy baseline"));
}
fn capture(loaded: &specimen_config::LoadedSpecimens) -> Result<CapturedFonts, Error> {
    let mut fonts = BTreeMap::new();
    let mut metadata = BTreeMap::new();
    for family in &loaded.config.families {
        let path = loaded
            .cases
            .iter()
            .find(|case| case.family_id == family.id)
            .unwrap()
            .font
            .clone();
        let bytes = io(fs::read(path))?;
        if hash(&bytes) != family.provenance.expected_sha256 {
            return Err(fail(format!("font checksum mismatch for {}", family.id)));
        }
        metadata.insert(family.id.clone(), crate::metadata::extract(&bytes)?);
        fonts.insert(family.id.as_str(), bytes);
    }
    let mut cases = loaded.cases.clone();
    for case in &mut cases {
        case.axes = effective_axes(&fonts[case.family_id.as_str()], case)?;
        guard_reserved(&hash(&fonts[case.family_id.as_str()]), case)?;
    }
    let mut captured = Vec::new();
    for case in cases {
        let data = &fonts[case.family_id.as_str()];
        let variant = loaded
            .config
            .variants
            .iter()
            .find(|v| v.id == case.variant)
            .unwrap();
        let profile = loaded
            .config
            .profiles
            .iter()
            .find(|p| p.id == case.profile)
            .unwrap();
        let family = loaded
            .config
            .families
            .iter()
            .find(|f| f.id == case.family_id)
            .unwrap();
        let space = space(data, &case)?;
        let settings = Config {
            size_px: case.size_px,
            axes: case.axes.clone(),
            hinting: variant.hinting,
            output_bits: profile.output_bits,
            mono_threshold: profile.mono_threshold,
            gray_gamma: profile.gray_gamma,
            characters: loaded.config.characters.clone(),
            ..Config::default()
        };
        let request = ReferenceRequest {
            profile: case.profile.clone(),
            extensions: variant.extensions.clone(),
            settings: settings.clone(),
        };
        let result = crate::renderer::render(data, &request, variant.renderer());
        let (report, reason) = match result {
            Ok(report) => (Some(report), None),
            Err(error) => (None, Some(error.to_string())),
        };
        let capture = CapturedCase {
            family_id: case.family_id.clone(),
            size_px: case.size_px,
            axes: case.axes.clone(),
            profile: case.profile.clone(),
            provenance: family.provenance.clone(),
            space,
            report,
            reason,
        };
        captured.push(Captured {
            case,
            capture,
            layouts,
        });
    }
    Ok(CapturedFonts {
        cases: captured,
        metadata,
    })
}

